package net.officefloor.hq.app.access;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimStatus;

/**
 * The late charge as of the sheet's today: an OPEN claim past its due-by (its date plus the terms) gains the late
 * percent of its figure for every full 30 days it is overdue, rounded half to even to two decimals. The charge is
 * never bound by a statement; settling freezes it into the settled due.
 */
public record LateCharge(LocalDate today, int terms, BigDecimal pct) {

    /** The claim's late charge on its figure (zero when it is not overdue, or has no figure). */
    public BigDecimal on(Claim claim, BigDecimal figure) {
        BigDecimal none = BigDecimal.ZERO.setScale(2);
        if (figure == null || claim.getStatus() != ClaimStatus.OPEN) {
            return none;
        }
        long overdue = ChronoUnit.DAYS.between(claim.getDate().plusDays(terms), today);
        long periods = overdue > 0 ? overdue / 30 : 0;
        if (periods == 0) {
            return none;
        }
        return figure.multiply(pct).multiply(BigDecimal.valueOf(periods)).movePointLeft(2)
                .setScale(2, RoundingMode.HALF_EVEN);
    }

    /** The figure with the claim's late charge added on top; null without a figure. */
    public BigDecimal due(Claim claim, BigDecimal figure) {
        return figure == null ? null : figure.setScale(2).add(on(claim, figure));
    }
}
package net.officefloor.hq.app.rollup;

import java.math.BigDecimal;

/** A person's figures: their claimed and their due-total (null: n/a), both with two decimals. */
public record Figures(String name, BigDecimal claimed, BigDecimal dueTotal) {

    /** Whether the claimed or the due-total differs from {@code other}'s. */
    boolean movedFrom(Figures other) {
        return other == null || !claimed.equals(other.claimed) || !java.util.Objects.equals(dueTotal, other.dueTotal);
    }
}

